scripts.杨湖对话.txt:
//和杨湖对话

	If ($Event == 610) @Event610;

	Say("杨湖：独孤兄弟，大殿的后门就通往后花园。",100);
	Return;
	
@Event610:
	Say("杨湖：帮主放心，属下一定安排妥当！",100);
	Say("杨湖：独孤兄弟，可要好好照顾我们帮主！",100);
	Return;

scripts.封玉书对话.txt:
//和封玉书对话

	Say("封玉书：姓杨的越来越专断了！哼，小子，别以为姓杨的帮着你，就可以在天王帮高枕无忧。", 64);
	Return;

scripts.路云远对话.txt:
//和路云远对话

	If ($Event == 610) @Event610;
	
	Say("路云远：独孤少侠果然是一表人材。怪不得……老夫老了，管不了这么多事了！");
	Return;
	
@Event610:
	Say("路云远：帮主千万要小心！");
	Reurn;

scripts.天王帮众对话1.txt:
// 和帮众对话

	If ($Event == 610) @Event610;

	Say("“地煞星”焦俊：封左使怎么敢这么和帮主说话？！");
	Return;
	
@Event610:
	Say("“地煞星”焦俊：我早就瞧封玉书有古怪了……原来是金国的走狗！");
	Return;

scripts.天王帮众对话2.txt:
// 和帮众对话

	If ($Event == 610) @Event610;

	Say("“轰天锤”凌正：既然杨右使说你是好人，俺就信你是好人！");
	Return;
	
@Event610:
	Say("“轰天锤”凌正：俺一早就瞧不惯封玉书了，平时飞扬跋扈的，不把帮主放在眼里。");
	Return;

scripts.天王帮众对话3.txt:
// 和帮众对话

	If ($Event == 610) @Event610;

	Say("“铁面郎”裴良：王前使为人最讲意气，怎么会背叛天王帮呢？我不信！");
	Return;
	
@Event610:
	Say("“铁面郎”裴良：真是知人知面不知心啊，想不到封左使竟是五色教的奸细！");
	Return;

scripts.天王帮众对话4.txt:
// 和帮众对话

	If ($Event == 610) @Event610;

	Say("“镇三川”崔信：封左使是帮中的元老，他说的话总不会一点道理也没有吧？");
	Return;
	
@Event610:
	Say("“镇三川”崔信：真没想到，真是做梦也没想到。");
	Return;

scripts.杨瑛的同伴对话.txt:
// 杨瑛的同伴对话

	Say("杨瑛：这次封玉书的叛逃对帮众的士气影响一定很大。", 39);
	Say("独孤剑：不要太担心，也许这次的事情让大家看清了真正的敌人——是金国和五色教，而不是岳元帅。", 1);
	Say("杨瑛：……", 39);
	Return;

